import React from 'react';
import SearchBarUnified from './components/SearchBarUnified';
import ProductSlider from './components/ProductSlider';
import CategorySlider from './components/CategorySlider';

// Ejemplo: data figurativa (cada item debe tener {id, imageUrl})
const productosHome = [
  { id: 1, imageUrl: 'https://picsum.photos/id/101/1200/800' },
  { id: 2, imageUrl: 'https://picsum.photos/id/102/1200/800' },
  { id: 3, imageUrl: 'https://picsum.photos/id/104/1200/800' },
  { id: 4, imageUrl: 'https://picsum.photos/id/105/1200/800' },
  { id: 5, imageUrl: 'https://picsum.photos/id/106/1200/800' },
  { id: 6, imageUrl: 'https://picsum.photos/id/107/1200/800' },
];

// Categorías orden fijo (si querés, reemplazá por las de tu App.js)
const categorias = [
  { id: 1, name: 'Gastronomía',   imageUrl: '/icons/gastronomia.png' },
  { id: 2, name: 'Indumentaria',  imageUrl: '/icons/indumentaria.png' },
  { id: 3, name: 'Hogar', imageUrl: '/icons/indumentaria.png' },
  { id: 4, name: 'Tecnología',  imageUrl: '/icons/indumentaria.png' },
  { id: 5, name: 'Deportes',  imageUrl: '/icons/indumentaria.png' },
  { id: 6, name: 'Belleza' , imageUrl: '/icons/indumentaria.png' }
];

export default function App(){
  return (
    <div className="page">
      <header className="header">
        <div className="logo">
          <a href="/">
            <img src="/logo-conecta.png" alt="Conecta Pinamar" />
          </a>
        </div>

        <SearchBarUnified />
      </header>

      <section>
        <h2 className="title">SOLO POR ESTA SEMANA</h2>
        <ProductSlider id="semana" images={productosHome} />
      </section>

      <section>
        <h2 className="title">CATEGORÍAS</h2>
       <CategorySlider categories={categorias} />

      </section>

      <section>
        <h2 className="title">DESTACADOS</h2>
        <ProductSlider id="destacados" images={productosHome} />
      </section>
    </div>
  );
}
